    "duty": "Seit 29.07.2026 heißt das GEG Gebäudemodernisierungsgesetz (GModG). Die 65-%-Pflicht (§ 71) und das Betriebsverbot für 30 Jahre alte Kessel (§ 72) sind weggefallen; die Prüfpflichten §§ 60a–60c und die Klima-Inspektion §§ 74–78 bleiben.",
