    "duty": "§ 71 (65 % erneuerbare Energie beim Heizungseinbau) und § 72 (Betriebsverbot alter Heizkessel) lauten nur noch '(weggefallen)'. Eine Beratungspflicht vor Einbau fossiler Heizungen (früher § 71 Abs. 11) ist im Bundesrecht nicht mehr auffindbar.",
    "appHint": "Bei Kesseltausch keine Bundes-Austauschpflicht anzeigen; stattdessen auf § 43 (Bio-Anteil) und Landesrecht (BW, HH, SH) prüfen.",
