    "conditions": "Nur Einbau in ein bestehendes Gebäude; gilt auch für Flüssiggas. Hybrid mit Wärmepumpe (Leistungsanteil 30 bzw. 40 %) gilt als erfüllt; 2029–2034 auch Solarthermie oder Lüftung mit Wärmerückgewinnung (≥ 73 %).",
