    "prereq": null,
    "duty": "Der Eigentümer (bzw. Betreiber) muss sicherstellen, dass ab 2029 mind. 10 %, ab 2030 15 %, ab 2035 30 % und ab 2040 60 % der Wärme aus Biomethan, Bioöl, biogenem Flüssiggas oder Wasserstoff stammen. Lieferanten bestätigen das mit der Abrechnung (§ 96 Abs. 4).",
    "appHint": "Beim Anlegen einer neuen Gas-/Ölheizung mit Einbaudatum nach 29.07.2026 den Kunden-Hinweis zur Bio-Quote ins Übergabeprotokoll aufnehmen.",
